    try std.testing.expectEqual(implementation.render_v1_header.size, binding.render_v1_header.size);
    try std.testing.expectEqual(implementation.render_v1_header.interface_id_lo, binding.render_v1_header.interface_id_lo);
    try std.testing.expectEqual(implementation.device_v1_header.size, binding.device_v1_header.size);
    try std.testing.expectEqual(implementation.device_v1_header.interface_id_lo, binding.device_v1_header.interface_id_lo);
    try std.testing.expectEqual(implementation.color_v1_header.size, binding.color_v1_header.size);
